ValidationRule.errorConditionFormula:
AND(OR($RecordType.Name = "Agent Acquisition",$RecordType.Name = "Renewal -Agent Acquisition"),
 (
  OR(
    (text(Approval_Status__c) !='pending' || text(Approval_Status__c) ==null) && text(StageName) = 'Quotation Pending Approval',
	(text(Approval_Status__c) !='approved' || text(Approval_Status__c) ==null)&& text(StageName) = 'Quotation & Agreement Approved',
    (text(Approval_Status__c) !='rejected' || text(Approval_Status__c) ==null)&& text(StageName) = 'Quotation Rejected'
	 )
  )
)
